import re
ttl = open(GRAPH_TTL).read()
lines = ttl.splitlines()
subj=None
triples=[]
for raw in lines:
    line=raw.strip()
    if not line: continue
    # Determine terminator
    if line.endswith('.'):
        body = line[:-1].strip()
    elif line.endswith(';'):
        body = line[:-1].strip()
    else:
        body = line
    body = body.lstrip(';').strip()
    if not body: continue
    m = re.match(r'^<([^>]+)>\s+(.+)$', body)
    if m:
        subj = m.group(1); rest = m.group(2)
    else:
        rest = body
    m2 = re.match(r'^<([^>]+)>\s+(.+)$', rest)
    if not m2: continue
    p = m2.group(1); o = m2.group(2).strip()
    if subj is None: continue
    triples.append((subj,p,o))

brick = "https://brickschema.org/schema/Brick#"
refpre = "https://brickschema.org/schema/Brick/ref#"
rdfs = "http://www.w3.org/2000/01/rdf-schema#"

zone_label = {}
room_zone = {}
sensor_room = {}
sensor_ts  = {}

for s, p, o in triples:
    if p == rdfs + "label":
        label = o.strip('"')
        if "#Zone_F" in s:
            zone_label[s] = label
    if p == brick + "hasLocation" and "#Room_F" in s:
        room_zone[s] = o
    if p == brick + "isPointOf" and "Occupancy_Sensor" in s:
        sensor_room[s] = o
    if p == refpre + "hasExternalReference" and "Occupancy_Sensor" in s and o.startswith("urn:buildgraph:tsref:"):
        sensor_ts[s] = o.split("urn:buildgraph:tsref:")[-1]

print("zones:", len(zone_label))
print("rooms in zone map:", len(room_zone))
print("occupancy sensors mapped:", len(sensor_room), len(sensor_ts))
print("zone labels:", sorted(set(zone_label.values())))

